import sys
from collections import deque

def bfs(start, adj, n):
    dist = [-1] * (n + 1)
    q = deque([start])
    dist[start] = 0
    far_node = start
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
                if dist[v] > dist[far_node]:
                    far_node = v
    return far_node, dist

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    try:
        n = int(next(it))
    except StopIteration:
        return
    if n <= 1:
        print(0)
        return
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        try:
            u = int(next(it))
            v = int(next(it))
        except StopIteration:
            break
        if 1 <= u <= n and 1 <= v <= n:
            adj[u].append(v)
            adj[v].append(u)
    # start from any node that exists (1)
    start = 1
    while start <= n and not adj[start]:
        start += 1
    if start > n:
        print(0)
        return
    far1, _ = bfs(start, adj, n)
    far2, dist = bfs(far1, adj, n)
    print(dist[far2])

if __name__ == "__main__":
    solve()
